import { log } from "../utils/index.js";
export const DEFAULT_PII_COLUMNS = [
    "email",
    "e_mail",
    "ssn",
    "social_security",
    "phone",
    "mobile",
    "first_name",
    "last_name",
    "full_name",
    "middle_name",
    "given_name",
    "family_name",
    "surname",
    "forename",
    "maiden_name",
    "preferred_name",
    "legal_name",
    "address",
    "street",
    "zip",
    "postal_code",
    "dob",
    "date_of_birth",
    "credit_card",
    "card_number",
    "cc_number",
    "cvv",
    "password",
    "passwd",
    "pwd",
    "api_key",
    "secret",
    "token",
    "ip_address",
    "ipaddress",
];
const EMAIL_RE = /([A-Za-z0-9._%+-])[A-Za-z0-9._%+-]*@([A-Za-z0-9-])[A-Za-z0-9.-]*\.([A-Za-z]{2,})/g;
const SSN_RE = /(?<!\d)\d{3}-\d{2}-(\d{4})(?!\d)/g;
const US_PHONE_RE = /(?<!\d)(?:\+?1[-.\s]?)?\(?\d{3}\)?[-.\s]?\d{3}[-.\s]?(\d{4})(?!\d)/g;
const IPV4_RE = /(?<!\d)(?:\d{1,3}\.){3}(\d{1,3})(?!\d)/g;
const CARD_RE = /(?<!\d)(?:\d[ -]?){12,18}\d(?!\d)/g;
export function maskEmail(value) {
    return value.replace(EMAIL_RE, (_m, local, domain, tld) => `${local}***@${domain}***.${tld}`);
}
export function maskPhone(value) {
    return value.replace(US_PHONE_RE, (_m, last4) => `***-***-${last4}`);
}
export function maskSSN(value) {
    return value.replace(SSN_RE, (_m, last4) => `***-**-${last4}`);
}
export function maskIP(value) {
    return value.replace(IPV4_RE, (_m, last) => `***.***.***.${last}`);
}
function isLuhnValid(digits) {
    if (digits.length < 13 || digits.length > 19)
        return false;
    let sum = 0;
    let alt = false;
    for (let i = digits.length - 1; i >= 0; i--) {
        const code = digits.charCodeAt(i);
        if (code < 48 || code > 57)
            return false;
        let n = code - 48;
        if (alt) {
            n *= 2;
            if (n > 9)
                n -= 9;
        }
        sum += n;
        alt = !alt;
    }
    return sum % 10 === 0;
}
export function maskCard(value) {
    return value.replace(CARD_RE, (match) => {
        const digits = match.replace(/[ -]/g, "");
        if (!isLuhnValid(digits))
            return match;
        const last4 = digits.slice(-4);
        return `****-****-****-${last4}`;
    });
}
export function maskGeneric(value) {
    if (value.length === 0)
        return value;
    if (value.length === 1)
        return "*";
    const keep = value.slice(0, 1);
    const tailLen = Math.min(value.length - 1, 8);
    return keep + "*".repeat(tailLen);
}
export function applyPatternMasks(value) {
    let out = value;
    out = maskEmail(out);
    out = maskCard(out);
    out = maskSSN(out);
    out = maskPhone(out);
    out = maskIP(out);
    return out;
}
function matchPIIColumn(key, columns, patterns) {
    const lower = key.toLowerCase();
    for (const needle of columns) {
        if (lower.includes(needle))
            return `substring "${needle}"`;
    }
    for (const pattern of patterns) {
        if (pattern.test(lower))
            return `pattern ${pattern}`;
    }
    return null;
}
export function isPIIColumn(key, columns = DEFAULT_PII_COLUMNS, patterns = []) {
    return matchPIIColumn(key, columns, patterns) !== null;
}
function maskByColumn(value) {
    const patternMasked = applyPatternMasks(value);
    if (patternMasked !== value)
        return patternMasked;
    return maskGeneric(value);
}
export function redactPII(value, options = {}) {
    const cleanedExtras = options.extraColumns?.filter((s) => s.length > 0);
    const columns = options.columns ??
        (cleanedExtras && cleanedExtras.length > 0
            ? [...DEFAULT_PII_COLUMNS, ...cleanedExtras]
            : DEFAULT_PII_COLUMNS);
    const patterns = options.columnPatterns ?? [];
    const parseJsonStrings = options.parseJsonStrings !== false;
    const stats = { fields: 0, columns: new Set() };
    const result = walk(value, columns, patterns, null, stats, parseJsonStrings);
    if (stats.fields > 0) {
        log("info", `[redact] masked ${stats.fields} field(s) across column(s): ${[...stats.columns].join(", ")}`);
    }
    else {
        log("info", "[redact] no PII fields detected");
    }
    return result;
}
const SHOW_COLUMNS_KEY = "field";
const SHOW_INDEX_KEY = "column_name";
function findKey(row, target) {
    for (const key of Object.keys(row)) {
        if (key.toLowerCase() === target)
            return key;
    }
    return null;
}
export function filterIntrospectionRows(rows, kind, isPII) {
    if (!Array.isArray(rows))
        return null;
    if (rows.length === 0)
        return rows;
    const keyName = kind === "show_index" ? SHOW_INDEX_KEY : SHOW_COLUMNS_KEY;
    const sample = rows[0];
    if (sample == null || typeof sample !== "object" || Array.isArray(sample)) {
        return null;
    }
    const sampleKey = findKey(sample, keyName);
    if (sampleKey === null)
        return null;
    let hidden = 0;
    const out = rows.filter((row) => {
        if (row == null || typeof row !== "object" || Array.isArray(row)) {
            return true;
        }
        const obj = row;
        const colKey = findKey(obj, keyName);
        if (colKey === null)
            return true;
        const value = obj[colKey];
        if (typeof value !== "string")
            return true;
        if (isPII(value)) {
            hidden++;
            return false;
        }
        return true;
    });
    if (hidden > 0) {
        log("info", `[redact] filtered ${hidden} PII column(s) from ${kind} result`);
    }
    return out;
}
function walk(value, columns, patterns, parentMatch, stats, parseJsonStrings) {
    if (value == null)
        return value;
    if (typeof value === "string") {
        if (parentMatch !== null) {
            stats.fields++;
            return maskByColumn(value);
        }
        if (parseJsonStrings) {
            const trimmed = value.trim();
            if (trimmed.startsWith("{") || trimmed.startsWith("[")) {
                try {
                    const parsed = JSON.parse(trimmed);
                    if (typeof parsed === "object" && parsed !== null) {
                        return JSON.stringify(walk(parsed, columns, patterns, null, stats, parseJsonStrings));
                    }
                }
                catch {
                }
            }
        }
        return applyPatternMasks(value);
    }
    if (Array.isArray(value)) {
        return value.map((item) => walk(item, columns, patterns, parentMatch, stats, parseJsonStrings));
    }
    if (typeof value === "object") {
        if (value instanceof Date)
            return value;
        if (typeof Buffer !== "undefined" && Buffer.isBuffer(value))
            return value;
        const out = {};
        for (const [key, child] of Object.entries(value)) {
            const match = matchPIIColumn(key, columns, patterns);
            if (match !== null) {
                log("info", `[redact] column "${key}" matched PII rule: ${match}`);
                stats.columns.add(key);
            }
            out[key] = walk(child, columns, patterns, match, stats, parseJsonStrings);
        }
        return out;
    }
    return value;
}
